function applyTheme(){
  const t=THEMES[sett.theme]||THEMES.dark;
  const p=document.getElementById('tbj-panel');
  if(!p) return;
  const bjWrap=document.querySelector('.blackjack-wrap');
  const BW=t.outlineW;
  const B=BW+'px solid '+t.outline;

  // Override Torn's page content container border — target by class names we know from the MHT
  const tornContainer=document.querySelector('.contentPlaceholder___ctRf4')||
                      (bjWrap&&bjWrap.closest('[class*="contentPlaceholder"]'))||
                      (bjWrap&&bjWrap.closest('[class*="content"]'));
  if(tornContainer){
    tornContainer.style.borderColor=t.outline;
    tornContainer.style.borderRadius='10px';
  }

  if(sett.theme==='torn'){
    // Torn: thick outline inset on bjWrap + matching panel borders + felt texture
    if(bjWrap){
      bjWrap.style.outline=B;
      bjWrap.style.outlineOffset='-'+BW+'px';
      bjWrap.style.borderRadius='10px 10px 0 0';
      bjWrap.style.borderColor=t.outline;
      if(bjWrap.parentElement) bjWrap.parentElement.style.boxShadow='none';
    }
    p.style.position=''; p.style.left='';
    if(bjWrap){
      const bjR=bjWrap.getBoundingClientRect();
      const pR=p.getBoundingClientRect();
      p.style.width=bjR.width+'px';
      p.style.marginLeft=(bjR.left-pR.left)+'px';
    }
    p.style.boxSizing='border-box'; p.style.marginTop='-2px';
    p.style.borderLeft=B; p.style.borderRight=B; p.style.borderBottom=B;
    p.style.borderTop='none';
    p.style.borderRadius='0 0 10px 10px';
    p.style.boxShadow='none';
    // Apply felt texture; use background shorthand to set both color and image together
    p.style.background=t.bgImg
      ? t.bgImg+' '+t.bgPos+'/'+t.bgSize+', '+t.bg
      : t.bg;
  } else {
    // Dark/light: thin outline outside bjWrap + matching panel border, no texture
    if(bjWrap){
      bjWrap.style.outline=B;
      bjWrap.style.outlineOffset='0px';
      bjWrap.style.borderRadius='10px 10px 0 0';
      bjWrap.style.borderColor=t.outline;
      if(bjWrap.parentElement) bjWrap.parentElement.style.boxShadow='none';
    }
    p.style.position=''; p.style.left='';
    if(bjWrap){
      const bjR=bjWrap.getBoundingClientRect();
      const pR=p.getBoundingClientRect();
      p.style.width=(bjR.width+BW*2)+'px';
      p.style.marginLeft=(bjR.left-pR.left-BW)+'px';
    }
    p.style.boxSizing='border-box'; p.style.marginTop='0px';
    p.style.borderLeft=B; p.style.borderRight=B; p.style.borderBottom=B;
    p.style.borderTop='none';
    p.style.borderRadius='0 0 10px 10px';
    p.style.boxShadow='none';
    p.style.background=t.bg; // shorthand clears backgroundImage automatically
  }
  const bar=document.getElementById('tbj-bar');
  if(bar){ bar.style.borderBottomColor=t.border2; }
  // bg2 elements need explicit backgroundImage:none to block any panel texture bleeding through
  p.querySelectorAll('[data-tbj-bg2]').forEach(el=>{
    el.style.backgroundImage='none';
    el.style.background=t.bg2;
    el.style.borderColor=t.border2;
  });
  p.querySelectorAll('[data-tbj-text]').forEach(el=>el.style.color=t.text);
  p.querySelectorAll('[data-tbj-accent]').forEach(el=>el.style.color=t.accent);
  p.querySelectorAll('[data-tbj-label]').forEach(el=>el.style.color=t.label);
  p.querySelectorAll('[data-tbj-win]').forEach(el=>el.style.color=t.win);
  p.querySelectorAll('[data-tbj-loss]').forEach(el=>el.style.color=t.loss);
  p.querySelectorAll('[data-tbj-push]').forEach(el=>el.style.color=t.push);
  p.querySelectorAll('[data-tbj-pl]').forEach(el=>el.style.color=t.pl);
  p.querySelectorAll('[data-tbj-btn]').forEach(el=>{el.style.backgroundImage='none';el.style.background=t.btn;el.style.borderColor=t.border;el.style.color=t.btnText;});
  p.querySelectorAll('[data-tbj-save]').forEach(el=>{el.style.backgroundImage='none';el.style.background=t.save;el.style.color=t.saveText;});
  p.querySelectorAll('[data-tbj-link]').forEach(el=>el.style.color=t.link);
  p.querySelectorAll('[data-tbj-danger]').forEach(el=>el.style.color=t.danger);
  p.querySelectorAll('[data-tbj-warn]').forEach(el=>el.style.color=t.warn);
  p.querySelectorAll('[data-tbj-auto]').forEach(el=>el.style.color=t.auto);
  p.querySelectorAll('[data-tbj-pip]').forEach(el=>{ if(!el.dataset.tbjActive) el.style.background=t.pip; });
  p.querySelectorAll('[data-tbj-donate]').forEach(el=>{el.style.backgroundImage='none';el.style.background=t.donate;el.style.borderColor=t.donateBorder;el.style.color=t.donateText;});
  p.querySelectorAll('[data-tbj-divider]').forEach(el=>el.style.borderColor=t.border2);
  const actionEl=document.getElementById('tbj-action');
  if(actionEl&&actionEl.textContent.startsWith('BET')) actionEl.style.color=t.accent;
}
// Store starting token count for accurate hand tracking
