// ── Update helpers ────────────────────────────────────────────────────────────
function updateCharlie(n){
  for(let i=1;i<=6;i++){
    const pip=document.getElementById('tbj-pip'+i);
    if(pip) pip.style.background=i<=n?(i===6?'#fbbf24':'#22c55e'):'#1a2e42';
  }
}

function updateKelly(){
  const el=document.getElementById('tbj-kelly');
  if(!el) return;
  const t=THEMES[sett.theme]||THEMES.dark;
  const br=getBankroll();
  if(!br){el.innerHTML=`<span style="color:${t.border2}">—</span>`;return;}
  const opt=optimalBet(br);
  if(!goalTarget){
    el.innerHTML=`<span style="color:${t.label}">Safe bet:</span> <span style="color:${t.accent}">${fmt(opt)}</span><br><span style="color:${t.border2}">Set goal above</span>`;
    return;
  }
  const pg=pGoalDaily(br,goalTarget,opt)*100;
  const days=Math.ceil(goalTarget/(DAILY*EDGE*opt));
  el.innerHTML=
    `<span style="color:${t.warn}">Goal: ${fmt(goalTarget)}</span><br>`+
    `<span style="color:${t.accent}">Bet: ${fmt(opt)}</span><br>`+
    `P(goal): <span style="color:${pg>50?t.win:t.warn}">${pg.toFixed(1)}%</span> `+
    `<span style="color:${t.border2}">~${days}d</span><br>`+
    `EV/day: <span style="color:${t.link}">${fmt(DAILY*EDGE*opt)}</span>`;
}

function updateStats(){
  const t=THEMES[sett.theme]||THEMES.dark;
  // Session stats
  const sessEl=document.getElementById('tbj-sess-stats');
  const sp=(sess.profit||0)>=0?t.win:t.loss;
  if(sessEl) sessEl.innerHTML=
    `W/L/P: <span style="color:${t.win}">${sess.w||0}</span>/<span style="color:${t.loss}">${sess.l||0}</span>/<span style="color:${t.push}">${sess.p||0}</span><br>`+
    `P/L: <span style="color:${sp}">${fmt(sess.profit||0)}</span>`;
  // Lifetime stats
  const lifeEl=document.getElementById('tbj-life-stats');
  const lp=(life.profit||0)>=0?t.win:t.loss;
  if(lifeEl) lifeEl.innerHTML=
    `W/L/P: <span style="color:${t.win}">${life.w||0}</span>/<span style="color:${t.loss}">${life.l||0}</span>/<span style="color:${t.push}">${life.p||0}</span><br>`+
    `P/L: <span style="color:${lp}">${fmt(life.profit||0)}</span>`;
  // Bar inline
  const w=document.getElementById('tbj-w');
  const l=document.getElementById('tbj-l');
  const pp=document.getElementById('tbj-p');
  const pl=document.getElementById('tbj-pl');
  if(w) w.textContent=sess.w||0;
  if(l) l.textContent=sess.l||0;
  if(pp) pp.textContent=sess.p||0;
  if(pl){pl.textContent=fmt(sess.profit||0);pl.style.color=(sess.profit||0)>=0?t.win:t.loss;}
}
